# Simulated sites for the starting-value benchmark (fit.jl): the acquisition of examples/data/cases.jl (shot-noise precision, 15% background in a 300 nm cube around the ROI center at the origin, 1 s), but every site with its own true parameters, as real sites vary. Run from the LocMoFit.jl folder:
#     julia --project=../DynMoSim benchmarks/start/generate.jl
# Writes data/<case>_locs.csv (localizations, SMAPpy column names, plus the site number and is_signal) and data/<case>_truth.csv (one row of true parameters per site). The data are regenerated by this script and need not be committed (Xoshiro streams can change between Julia versions).
#   ring (200 sites, 100 signal localizations): r in [30, 80] nm, the axis tilted up to 60°;
#   spcap (100 sites, 250): s in [30, 60] nm, κ′ in [0.1, 0.9], the axis tilted up to 45°;
#   double_ring (100 sites, 160, equal shares): two parallel, coaxial rings of the same radius r in [35, 65] nm, d in [35, 65] nm apart (z2 = d), so that r²/2 and (d/2)², the covariance's eigenvalues across and along the axis, cross; the axis tilted up to 60°;
#   spcap_ring (100 sites, 300; 30% ring, 70% cap): a ring r1 in [35, 65] nm and a cap with its apex on the ring's axis and its axis along it, s2 in [20, 35] nm, κ′ in [0.3, 0.8], its rim 20–50 nm above the ring (z2 = 2 s2 κ′ + that); the axis tilted up to 45°;
# every axis in any azimuth, and the center (a cap's apex, ring 1's center) up to 30 nm from the ROI center laterally and 60 nm axially.
include(joinpath(@__DIR__, "..", "..", "examples", "data", "cases.jl"))
const OUT = joinpath(@__DIR__, "data")
mkpath(OUT)

const SITES = (
    ring=(n=200, seed=11, names=(:x, :y, :z, :r, :theta, :phi)),
    spcap=(n=100, seed=12, names=(:x, :y, :z, :s, :eta, :theta, :phi)),
    double_ring=(
        n=100,
        seed=13,
        names=(
            :x1, :y1, :z1, :r1, :theta1, :phi1, :x2, :y2, :z2, :r2, :theta2, :phi2, :omega2
        ),
    ),
    spcap_ring=(
        n=100,
        seed=14,
        names=(
            :x1,
            :y1,
            :z1,
            :r1,
            :theta1,
            :phi1,
            :x2,
            :y2,
            :z2,
            :s2,
            :eta2,
            :theta2,
            :phi2,
            :omega2,
        ),
    ),
)

# the true parameters of one site, drawn with u(a, b), uniform on [a, b]
function draw(name, u)
    if name === :ring || name === :spcap
        pose = (x=u(-30, 30), y=u(-30, 30), z=u(-60, 60), phi=u(-π, π))
        name === :ring && return (;
            pose...,
            r=u(30, 80),
            theta=u(0, deg2rad(60)),
            sigma=0.0,
            logit_prob=LOGIT_SIGNAL,
        )
        return (;
            pose...,
            s=u(30, 60),
            eta=atanh(u(0.1, 0.9)),
            theta=u(0, deg2rad(45)),
            sigma=0.0,
            logit_prob=LOGIT_SIGNAL,
        )
    end
    pose = (
        x1=u(-30, 30),
        y1=u(-30, 30),
        z1=u(-60, 60),
        phi1=u(-π, π),
        x2=0.0,
        y2=0.0,
        theta2=0.0,
        phi2=0.0,
        sigma=0.0,
        logit_prob=LOGIT_SIGNAL,
    )
    if name === :double_ring
        r = u(35, 65)
        return (; pose..., r1=r, r2=r, z2=u(35, 65), theta1=u(0, deg2rad(60)), omega2=0.0)
    end
    s, κ = u(20, 35), u(0.3, 0.8)
    return (;
        pose...,
        r1=u(35, 65),
        s2=s,
        eta2=atanh(κ),
        z2=2s * κ + u(20, 50),
        theta1=u(0, deg2rad(45)),
        omega2=log(7 / 3),
    )
end

for (name, spec) in pairs(SITES)
    rng = Xoshiro(spec.seed)
    case = CASES[name]
    open(joinpath(OUT, "$(name)_locs.csv"), "w") do locs_io
        open(joinpath(OUT, "$(name)_truth.csv"), "w") do truth_io
            println(locs_io, "site,x_nm,y_nm,z_nm,x_err_nm,y_err_nm,z_err_nm,is_signal")
            println(truth_io, join(("site", spec.names...), ","))
            for site in 1:(spec.n)
                truth = draw(name, (a, b) -> a + (b - a) * rand(rng))
                locs, gt = simulate_site(rng, (; case..., truth=truth))
                t, g = smaptable(locs), smaptable(gt)
                for i in eachindex(t.x_nm)
                    println(
                        locs_io,
                        join(
                            (
                                site,
                                t.x_nm[i],
                                t.y_nm[i],
                                t.z_nm[i],
                                t.x_err_nm[i],
                                t.y_err_nm[i],
                                t.z_err_nm[i],
                                Int(g.is_signal[i]),
                            ),
                            ",",
                        ),
                    )
                end
                println(truth_io, join((site, (truth[k] for k in spec.names)...), ","))
            end
        end
    end
    println("$name: $(spec.n) sites")
end
